from collections import deque

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def build(tree):
    # LeetCode list -> linked nodes. Each popped parent takes the next two slots.
    if not tree or tree[0] is None:
        return None
    root = Node(tree[0])
    queue = deque([root])
    i = 1
    while queue and i < len(tree):
        node = queue.popleft()
        if i < len(tree) and tree[i] is not None:
            node.left = Node(tree[i])
            queue.append(node.left)
        i += 1
        if i < len(tree) and tree[i] is not None:
            node.right = Node(tree[i])
            queue.append(node.right)
        i += 1
    return root

def solution(tree, target):
    root = build(tree)
    if root is None:
        return False                  # no root, so no root-to-leaf path
    stack = [(root, root.val)]        # (node, sum of the path from the root to it)
    while stack:
        node, total = stack.pop()
        if node.left is None and node.right is None:
            if total == target:       # only a leaf ends a path
                return True
            continue
        for child in (node.left, node.right):
            if child is not None:
                stack.append((child, total + child.val))
    return False

