from collections import deque

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def build(tree):
    # LeetCode list -> linked nodes. Each popped parent takes the next two slots.
    if not tree or tree[0] is None:
        return None
    root = Node(tree[0])
    queue = deque([root])
    i = 1
    while queue and i < len(tree):
        node = queue.popleft()
        if i < len(tree) and tree[i] is not None:
            node.left = Node(tree[i])
            queue.append(node.left)
        i += 1
        if i < len(tree) and tree[i] is not None:
            node.right = Node(tree[i])
            queue.append(node.right)
        i += 1
    return root

def solution(tree, target):
    # Record every root-to-leaf path as a full list, then sum each one.
    # Copying the path at every node is O(n * height).
    root = build(tree)
    if root is None:
        return False
    paths = []
    stack = [(root, [root.val])]
    while stack:
        node, path = stack.pop()
        if node.left is None and node.right is None:
            paths.append(path)
        for child in (node.left, node.right):
            if child is not None:
                stack.append((child, path + [child.val]))
    return any(sum(path) == target for path in paths)
